import { RuntimeLoader } from "@rive-app/webgl2";
import type { FC, ReactNode } from "react";
import { memo, useEffect, useMemo, useRef, useState } from "react";

// @rive-app/webgl2 defaults to loading its WASM runtime from unpkg (primary)
// and jsdelivr (fallback). Point both at the vendored copies so no network
// request is made when the canvas mounts.
RuntimeLoader.setWasmUrl("/assets/unpkg.com/rive.wasm");
RuntimeLoader.setWasmFallbackUrl("/assets/cdn.jsdelivr.net/rive_fallback.wasm");

